public final class FlowProblem {
    private final FlowNetwork network;
    private final int source;
    private final int sink;

    public FlowProblem(FlowNetwork network, int source, int sink) {
        if (network == null) {
            throw new IllegalArgumentException("Network must not be null.");
        }
        if (source < 0 || source >= network.size() || sink < 0 || sink >= network.size()) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices.");
        }

        this.network = network;
        this.source = source;
        this.sink = sink;
    }

    public FlowNetwork network() {
        return network;
    }

    public int source() {
        return source;
    }

    public int sink() {
        return sink;
    }
}

public final class MaxFlowSolver {
    public MaxFlowResult solve(FlowProblem problem) {
        ResidualNetwork residualNetwork = new ResidualNetwork(problem.network());
        int maxFlow = 0;

        while (true) {
            java.util.Optional<AugmentingPath> path = residualNetwork.findAugmentingPath(problem.source(), problem.sink());
            if (path.isEmpty()) {
                return new MaxFlowResult(maxFlow, residualNetwork.snapshot());
            }

            residualNetwork.augment(path.get());
            maxFlow += path.get().bottleneck();
        }
    }

    public MaxFlowResult solve(FlowNetwork network, int source, int sink) {
        return solve(new FlowProblem(network, source, sink));
    }

    public int calculateMaxFlow(int[][] graph, int source, int sink) {
        return solve(new FlowNetwork(graph), source, sink).getMaxFlow();
    }
}

public final class FlowNetwork {
    private final int[][] capacities;

    public FlowNetwork(int[][] capacities) {
        validate(capacities);
        this.capacities = IntMatrix.copyOf(capacities);
    }

    public int size() {
        return capacities.length;
    }

    public int capacity(int from, int to) {
        return capacities[from][to];
    }

    public int[][] copyCapacities() {
        return IntMatrix.copyOf(capacities);
    }

    private static void validate(int[][] capacities) {
        if (capacities == null || capacities.length == 0) {
            throw new IllegalArgumentException("Graph must not be empty.");
        }

        int size = capacities.length;
        for (int row = 0; row < size; row++) {
            if (capacities[row] == null || capacities[row].length != size) {
                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
            }
            for (int column = 0; column < size; column++) {
                if (capacities[row][column] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative.");
                }
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Optional;
import java.util.Queue;

public final class ResidualNetwork {
    private final int[][] capacities;

    public ResidualNetwork(FlowNetwork network) {
        capacities = network.copyCapacities();
    }

    public Optional<AugmentingPath> findAugmentingPath(int source, int sink) {
        boolean[] visited = new boolean[capacities.length];
        int[] parents = new int[capacities.length];
        Queue<Integer> queue = new ArrayDeque<>();

        Arrays.fill(parents, -1);
        queue.add(source);
        visited[source] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();

            for (int next = 0; next < capacities.length; next++) {
                if (visited[next] || capacities[current][next] <= 0) {
                    continue;
                }

                parents[next] = current;
                if (next == sink) {
                    return Optional.of(new AugmentingPath(source, sink, calculateBottleneck(source, sink, parents), parents));
                }

                visited[next] = true;
                queue.add(next);
            }
        }

        return Optional.empty();
    }

    public void augment(AugmentingPath path) {
        for (int vertex = path.sink(); vertex != path.source(); vertex = path.parentOf(vertex)) {
            int previous = path.parentOf(vertex);
            capacities[previous][vertex] -= path.bottleneck();
            capacities[vertex][previous] += path.bottleneck();
        }
    }

    public int[][] snapshot() {
        return IntMatrix.copyOf(capacities);
    }

    private int calculateBottleneck(int source, int sink, int[] parents) {
        int bottleneck = Integer.MAX_VALUE;

        for (int vertex = sink; vertex != source; vertex = parents[vertex]) {
            int previous = parents[vertex];
            bottleneck = Math.min(bottleneck, capacities[previous][vertex]);
        }

        return bottleneck;
    }
}

